if (result.decision === "YES") {
            return {
                statusCode: 200,
                body: JSON.stringify({
                    transaction: {
                        customFields: {
                            fraudDecision: result.decision
                        }
                    }
                })
            };
        } else {
            return {
                statusCode: 200,
                body: JSON.stringify({
                    transaction: {
                        status: braintree.Transaction.Status.GatewayRejected,
                        customFields: {
                            fraudDecision: result.decision
                        }
                    }
                })
            };
        }
